#!/usr/bin/env bash
# deploy_finans_oda_live.sh — Finans odasi %100 veri-gudumlu: uc /api/bi/finans/oda + temiz finans.html (SIFIR hardcoded).
# SUNUCUDA: cd /opt/krb-assessment && bash deploy_finans_oda_live.sh
# node --check + canli DB-hakikat + cokme kontrolu + OTOMATIK ROLLBACK. Yedek: *.bak_oda_<ts>
set -euo pipefail
cd /opt/krb-assessment
TS=$(date +%Y%m%d_%H%M%S)
T='f8a5d20f-ecf8-4ce2-a492-69268fbb03fa'

echo "== [0] finans.html (temiz, veri-gudumlu) yaz =="
cp shells/finans.html "finans.html.bak_oda_$TS" 2>/dev/null || true
base64 -d > shells/finans.html <<'B64_FIN'

B64_FIN
echo "  finans.html $(wc -c < shells/finans.html) bayt · hardcoded finansal sayi: $(grep -oE '[0-9]+[.,][0-9]+ ?M ₺|%[0-9]{2,}' shells/finans.html | grep -v '%100' | wc -l)"

echo "== [1] uc parcalarini yaz =="
cat > /opt/krb-assessment/_oda_endpoint.js <<'EP_EOF'
  // === FINANS_ODA_LIVE_V1 — tek kanonik uc: odanin HER sayisi canli kaynaktan; hardcoded YOK, kaynagi olmayan alan null(->"—") ===
  if (request.method === "GET" && url.pathname === "/api/bi/finans/oda") {
    if (response.headersSent) return;
    try {
      let session = await requireModuleAccess(request, "intelligence").catch(() => null);
      if (!session) { const _ss = await requireSahaAccess(request).catch(() => null); if (_ss && ["manager", "admin"].includes(_ss.sahaRole)) session = _ss; }
      if (!session) { if (!response.headersSent) sendJson(response, 403, { error: "yetki yok" }); return; }
      const T = session && session.tenantId; if (!T) { if (!response.headersSent) sendJson(response, 401, { error: "oturum yok" }); return; }
      const N = x => (x === null || x === undefined) ? null : Number(x);
      const M1 = x => (x === null || x === undefined) ? null : Math.round(Number(x) / 1e5) / 10;
      // CORE — v_finans_ticari_sermaye
      const v = (await query("SELECT * FROM v_finans_ticari_sermaye WHERE tenant_id = $1::uuid", [String(T)])).rows[0] || {};
      const dio = N(v.dio);
      const core = {
        net_satis_lastik: M1(v.net_satis_lastik), ciro_sirket: M1(v.ciro_tum_sirket), smm: M1(v.smm),
        brut_kar: M1(v.brut_kar), marj_pct: N(v.marj_pct), ticari_alacaklar: M1(v.ar_net),
        ticari_borclar: M1(v.ap_borc), finansman_yil: M1(v.finansman_yil),
        dso: N(v.dso), dio: dio, dpo: N(v.dpo), ccc: N(v.ccc), twc: M1(v.twc),
        bagli_sermaye_pct: N(v.bagli_sermaye_oran), devir: (dio && dio > 0) ? Math.round(365 / dio * 10) / 10 : null
      };
      // STOK — bi_stok_durumu LASTIK, en son export
      const _sk = (await query("SELECT grup_adi, sum(toplam_deger) d FROM bi_stok_durumu WHERE tenant_id::text=$1 AND export_date=(SELECT max(export_date) FROM bi_stok_durumu WHERE tenant_id::text=$1) AND grup_adi ILIKE 'LASTIK%' GROUP BY grup_adi ORDER BY d DESC", [String(T)])).rows;
      const stok = { toplam: Math.round(_sk.reduce((a, r) => a + Number(r.d || 0), 0) / 1e5) / 10, kirilim: _sk.map(r => ({ grup: r.grup_adi, deger: M1(r.d) })) };
      // GECIKMIS — bi_musteri_risk (en son snapshot/cari) + bi_cari_bakiye offset
      const _g = (await query("WITH r AS (SELECT DISTINCT ON (muhatap_kodu) muhatap_kodu kod, muhatap_adi ad, GREATEST(vadesi_gecmis,0) vg, musteri_mi, COALESCE(NULLIF(TRIM(grup),''),'') grup FROM bi_musteri_risk WHERE tenant_id::text=$1 ORDER BY muhatap_kodu, export_date DESC), cb AS (SELECT musteri_kodu, MIN(LEAST(tedarikci_bakiye,0)) borc FROM bi_cari_bakiye WHERE tenant_id::text=$1 GROUP BY musteri_kodu) SELECT r.ad, GREATEST(r.vg+COALESCE(cb.borc,0),0) net, r.vg gross FROM r LEFT JOIN cb ON cb.musteri_kodu=r.kod WHERE r.musteri_mi AND r.grup NOT ILIKE '%TEDAR%'", [String(T)])).rows;
      let gBrut = 0, gNet = 0; _g.forEach(r => { gBrut += Number(r.gross || 0); gNet += Number(r.net || 0); });
      const top = _g.map(r => ({ ad: r.ad, net: Number(r.net || 0) })).filter(x => x.net > 0).sort((a, b) => b.net - a.net).slice(0, 6).map(x => ({ ad: x.ad, net: Math.round(x.net / 1e5) / 10 }));
      const gecikmis = { brut: Math.round(gBrut / 1e5) / 10, net: Math.round(gNet / 1e5) / 10, top: top };
      // MARKA MARJ — bi_marj_atom 12 ay
      const marka = (await query("SELECT marka, round(sum(ciro)/1e6,1)::float8 ciro, round(sum(brut_kar)/nullif(sum(ciro),0)*100,1)::float8 marj, sum(adet)::int adet FROM bi_marj_atom WHERE tenant_id::text=$1 AND ay > ((SELECT max(ay) FROM bi_marj_atom WHERE tenant_id::text=$1) - 12*INTERVAL '1 month') AND ay <= (SELECT max(ay) FROM bi_marj_atom WHERE tenant_id::text=$1) GROUP BY marka HAVING sum(ciro)>0 ORDER BY ciro DESC LIMIT 12", [String(T)])).rows.map(r => ({ marka: r.marka, ciro: N(r.ciro), marj: N(r.marj), adet: N(r.adet) }));
      const _a = (await query("SELECT to_char(max(ay),'YYYY-MM') a FROM bi_marj_atom WHERE tenant_id::text=$1", [String(T)])).rows[0];
      const data = { as_of: _a ? _a.a : null, core: core, stok: stok, gecikmis: gecikmis, marka: marka, aging: null, leak: null };
      if (!response.headersSent) sendJson(response, 200, { data: data });
    } catch (e) { console.error("[finans-oda]", e && e.message); if (!response.headersSent) sendJson(response, 500, { error: String(e && e.message) }); }
    return;
  }
EP_EOF
cat > /opt/krb-assessment/_patch_oda.py <<'PY_EOF'
import sys
F="/opt/krb-assessment/server_container.mjs"; B="/opt/krb-assessment/_oda_endpoint.js"; MARK="FINANS_ODA_LIVE_V1"
s=open(F,encoding="utf-8").read()
if MARK in s: print("[oda] ZATEN YAMALI — atlaniyor"); sys.exit(0)
anchor='  // KOKPIT2_PREVIEW_ROUTE — yeni kokpit onizleme (canliya dokunmaz)'
if s.count(anchor)!=1: print("[oda] ANCHOR sayisi=%d (1 olmali) — DURDU"%s.count(anchor)); sys.exit(2)
ins=open(B,encoding="utf-8").read()
if not ins.endswith("\n"): ins+="\n"
open(F,"w",encoding="utf-8").write(s.replace(anchor, ins+anchor, 1))
print("[oda] OK — FINANS_ODA_LIVE_V1 ucu eklendi")
PY_EOF

echo "== [2] server yedek + yama =="
cp server_container.mjs "server_container.mjs.bak_oda_$TS"
python3 /opt/krb-assessment/_patch_oda.py || { echo "patch DURDU"; exit 1; }
echo "== [3] node --check =="
if node --check server_container.mjs; then echo "  server OK"; else echo "  FAIL — rollback"; cp "server_container.mjs.bak_oda_$TS" server_container.mjs; exit 1; fi
echo "  host marker srv: $(grep -c FINANS_ODA_LIVE_V1 server_container.mjs) · finans.html: $(grep -c FINANS_ODA_LIVE_V1 shells/finans.html)"

echo "== [4] build + deploy =="
docker build -t krb-assessment:secure .
docker compose up -d --force-recreate krb-assessment
sleep 5

echo "== [5] KONTEYNER + CANLI HAKIKAT + COKME =="
echo "  container: $(docker ps --filter name=krb-assessment --format '{{.Status}}')"
echo "  srv marker: $(docker exec krb-assessment grep -c FINANS_ODA_LIVE_V1 /app/server.mjs) · html marker: $(docker exec krb-assessment grep -c FINANS_ODA_LIVE_V1 /app/shells/finans.html)"
echo "  /api/bi/finans/oda (401=auth var/route OK; 404=yok; 500=hata): $(curl -s -o /dev/null -w '%{http_code}' http://localhost:8080/api/bi/finans/oda)"
echo "  --- ucun kaynagindan canli sayilar (odada gorunecekler) ---"
docker exec -i krb-assessment-postgres psql -U assessment_app -d assessment_platform -c "WITH r AS (SELECT DISTINCT ON (muhatap_kodu) muhatap_kodu kod, GREATEST(vadesi_gecmis,0) vg, musteri_mi, COALESCE(NULLIF(TRIM(grup),''),'') grup FROM bi_musteri_risk WHERE tenant_id::text='$T' ORDER BY muhatap_kodu, export_date DESC), cb AS (SELECT musteri_kodu, MIN(LEAST(tedarikci_bakiye,0)) borc FROM bi_cari_bakiye WHERE tenant_id::text='$T' GROUP BY musteri_kodu) SELECT round(sum(r.vg) FILTER (WHERE r.musteri_mi AND r.grup NOT ILIKE '%TEDAR%')/1e6,1) gecikmis_brut_M, round(sum(GREATEST(r.vg+COALESCE(cb.borc,0),0)) FILTER (WHERE r.musteri_mi AND r.grup NOT ILIKE '%TEDAR%')/1e6,1) gecikmis_net_M FROM r LEFT JOIN cb ON cb.musteri_kodu=r.kod;"
for i in 1 2 3; do curl -s -o /dev/null "http://localhost:8080/api/bi/finans/oda" || true; done
sleep 2
HS=$(docker logs --since 90s krb-assessment 2>&1 | grep -c ERR_HTTP_HEADERS_SENT || true)
echo "  ERR_HTTP_HEADERS_SENT (0 bekle): $HS · container: $(docker ps --filter name=krb-assessment --format '{{.Status}}')"
if [ "$HS" != "0" ]; then echo "  !!! COKME — OTOMATIK ROLLBACK !!!"; cp "server_container.mjs.bak_oda_$TS" server_container.mjs; cp "finans.html.bak_oda_$TS" shells/finans.html; docker build -t krb-assessment:secure . >/dev/null 2>&1 && docker compose up -d --force-recreate krb-assessment; echo "geri alindi"; exit 1; fi

echo "== [6] FINGERPRINT =="
docker exec -i krb-assessment-postgres psql -U assessment_app -d assessment_platform <<'SQL_EOF'
INSERT INTO bi_insa_gunlugu (adim, ne, neden, detay)
SELECT 'FINANS_ODA_LIVE_V1','Finans odasi TAM veri-gudumlu yeniden kuruldu: tek kanonik uc /api/bi/finans/oda (core=view, gecikmis=bi_musteri_risk+cari, marka=bi_marj_atom, stok=bi_stok_durumu); finans.html sifirdan, HICBIR hardcoded sayi yok, kaynagi olmayan (aging/sizinti) alan "—".','Onceki oda prototip hardcoded sayilarla canliya cikmisti (Fatih hakli tepki: sifir hardcoded). Placeholder ile kapatilmisti; simdi tum sayilar canli kaynaga bagli.','{"marker":"FINANS_ODA_LIVE_V1","uc":"/api/bi/finans/oda","dosya":"shells/finans.html","kaynak":["v_finans_ticari_sermaye","bi_musteri_risk","bi_cari_bakiye","bi_marj_atom","bi_stok_durumu"],"kaynaksiz":["aging","fiyat_sizintisi"]}'::jsonb
WHERE NOT EXISTS (SELECT 1 FROM bi_insa_gunlugu WHERE adim='FINANS_ODA_LIVE_V1');

INSERT INTO bi_yetenek (ad,tur,ne_ise_yarar,nasil,cekmece,durum,guven,kanit,aktif,eklendi_at,guncellendi_at,son_gorulme)
SELECT 'finans_odasi_veri','uc','Finans odasinin TEK kanonik veri ucu: core metrikler + gecikmis konsantrasyon + marka marji + stok kirilimi, hepsi canli kaynaktan tek JSON. Hardcoded yok.','GET /api/bi/finans/oda','finans','canli','taslak','{"marker":"FINANS_ODA_LIVE_V1"}'::jsonb,true,now(),now(),now()
WHERE NOT EXISTS (SELECT 1 FROM bi_yetenek WHERE ad='finans_odasi_veri');
SQL_EOF
docker exec -i krb-assessment-postgres psql -U assessment_app -d assessment_platform -c "SELECT adim FROM bi_insa_gunlugu WHERE adim='FINANS_ODA_LIVE_V1'; SELECT ad,durum FROM bi_yetenek WHERE ad='finans_odasi_veri';"
echo "== BITTI — Finans odasi %100 canli. Cmd+Shift+R. Her sayi /api/bi/finans/oda'dan; aging/sizinti '—'. =="
